INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MITHRAIC','Mithraic Mysteries (Roman imperial)',100,400)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_CLAUSS_MITHRAS','secondary scholarship','Manfred Clauss, The Roman Cult of Mithras: The God and His Mysteries (tr. R. Gordon, Routledge 2000)','Standard monograph on the iconography, grades, ritual and diffusion of the Roman Mithraic mysteries.'),
 ('SRC_BECK_MITHRAS','secondary scholarship','Roger Beck, The Religion of the Mithras Cult in the Roman Empire: Mysteries of the Unconquered Sun (Oxford 2006)','Cognitive/astronomical interpretation of the tauroctony, the mithraeum as cosmos, the grades and the Sun-Mithras relationship.')
INSERT INTO _e VALUES
 ('ENT_MITH_MYSTERIES','Mithraic Mysteries','tradition_hub','collective','Mithraic Mysteries','mystery cult, initiation, solar','A','Hub for the Roman initiatory cult of Mithras; well attested by ~600 mithraea and inscriptions across the empire (2nd-4th c. CE). Clauss ch.1.'),
 ('ENT_MITH_CORAX','Corax (Raven)','initiatory_grade','concept','Mithraic Mysteries','first grade of initiation','B','First/lowest of the seven Mithraic grades, under the tutelage of Mercury; attested in the grade-lists (Jerome, Ep.107) and the Felicissimus mosaic at Ostia. Clauss ch.10.'),
 ('ENT_MITH_NYMPHUS','Nymphus (Bridegroom)','initiatory_grade','concept','Mithraic Mysteries','second grade of initiation','B','Second Mithraic grade, the (grammatically masculine coinage) ''male bride'', under Venus; attested in the Ostia grade-mosaic and Jerome''s list. Clauss ch.10.'),
 ('ENT_MITH_MILES','Miles (Soldier)','initiatory_grade','concept','Mithraic Mysteries','third grade of initiation','B','Third Mithraic grade, the Soldier, under Mars; Tertullian (De corona 15) describes the miles refusing the offered crown. Clauss ch.10.'),
 ('ENT_MITH_LEO','Leo (Lion)','initiatory_grade','concept','Mithraic Mysteries','fourth grade of initiation','B','Fourth Mithraic grade, the Lion, under Jupiter; honey rather than water used in its purification (Porphyry, De antro 15). The first ''participating'' grade. Clauss ch.10.'),
 ('ENT_MITH_PERSES','Perses (Persian)','initiatory_grade','concept','Mithraic Mysteries','fifth grade of initiation','B','Fifth Mithraic grade, the Persian, under Luna (the Moon); attested in the Ostia grade-mosaic and Jerome''s list, evoking the cult''s claimed Persian origin. Distinct from the Greek Titan Perses (ENT_PERSES_TITAN). Clauss ch.10.'),
 ('ENT_MITH_HELIODROMUS','Heliodromus (Sun-Runner)','initiatory_grade','concept','Mithraic Mysteries','sixth grade of initiation','B','Sixth Mithraic grade, the Sun-Runner/courier of the Sun, under Sol; depicted with radiate crown, torch and whip. Clauss ch.10.'),
 ('ENT_MITH_PATER','Pater (Father)','initiatory_grade','concept','Mithraic Mysteries','seventh/highest grade of initiation','B','Seventh and highest Mithraic grade, the Father, under Saturn; leader of the local congregation (pater patrum at the apex). Clauss ch.10.'),
 ('ENT_MITH_CAUTES','Cautes','deity','deity','Mithraic Mysteries','torchbearer, dawn/rising sun','B','Torchbearer holding his torch upward, attendant of Mithras; with Cautopates forms the dadophoroi flanking the tauroctony, often read as sunrise/equinoxes. Clauss ch.9.'),
 ('ENT_MITH_CAUTOPATES','Cautopates','deity','deity','Mithraic Mysteries','torchbearer, dusk/setting sun','B','Torchbearer holding his torch downward, attendant of Mithras; paired with Cautes around the tauroctony, often read as sunset/the descending sun. Clauss ch.9.'),
 ('ENT_MITH_LEONTOCEPHALINE','Leontocephaline (Lion-headed Time-God)','deity','deity','Mithraic Mysteries','time, cosmos, eternity','C','Lion-headed serpent-entwined figure of Mithraic statuary, usually interpreted as a time/eternity deity and frequently equated with Aion/Zurvan; identity debated. Clauss ch.13; Beck.'),
 ('ENT_MITH_PETRA_GENETRIX','Petra Genetrix','deity','concept','Mithraic Mysteries','rock-birth, cosmogony','C','The ''birth-giving rock'' from which Mithras emerges (petra genetrix), a recurring image of the petrogenes Mithras in cult reliefs and dedications. Clauss ch.6.'),
 ('ENT_MITH_TAUROCTONY','Tauroctony','ritual','concept','Mithraic Mysteries','bull-slaying cult-scene, iconography','B','The central cult image: Mithras slaying the bull, attended by dog, serpent, scorpion, raven and the torchbearers; the icon of nearly every mithraeum and focus of astral interpretation. Clauss ch.7; Beck.');
