INSERT INTO _r VALUES
 ('ENT_SYN_MITHRAS','member_of','ENT_MITH_MYSTERIES','high','Mithras is the tutelary god of the Roman Mithraic mystery cult; wires the pre-existing Mithras into the new hub. Clauss ch.1.'),
 ('ENT_MITH_CORAX','member_of','ENT_MITH_MYSTERIES','high','Corax is the first of the seven grades of the Mithraic mysteries. Ostia grade-mosaic; Jerome Ep.107.'),
 ('ENT_MITH_NYMPHUS','member_of','ENT_MITH_MYSTERIES','high','Nymphus is the second of the seven Mithraic grades. Clauss ch.10.'),
 ('ENT_MITH_MILES','member_of','ENT_MITH_MYSTERIES','high','Miles is the third of the seven Mithraic grades. Tertullian De corona 15.'),
 ('ENT_MITH_LEO','member_of','ENT_MITH_MYSTERIES','high','Leo is the fourth of the seven Mithraic grades. Porphyry De antro 15.'),
 ('ENT_MITH_PERSES','member_of','ENT_MITH_MYSTERIES','high','Perses is the fifth of the seven Mithraic grades. Clauss ch.10.'),
 ('ENT_MITH_HELIODROMUS','member_of','ENT_MITH_MYSTERIES','high','Heliodromus is the sixth of the seven Mithraic grades. Clauss ch.10.'),
 ('ENT_MITH_PATER','member_of','ENT_MITH_MYSTERIES','high','Pater is the seventh and highest of the seven Mithraic grades. Clauss ch.10.'),
 ('ENT_MITH_CAUTES','member_of','ENT_MITH_MYSTERIES','high','Cautes, the upward torchbearer, is a standing figure of the Mithraic cult. Clauss ch.9.'),
 ('ENT_MITH_CAUTOPATES','member_of','ENT_MITH_MYSTERIES','high','Cautopates, the downward torchbearer, is a standing figure of the Mithraic cult. Clauss ch.9.'),
 ('ENT_MITH_LEONTOCEPHALINE','member_of','ENT_MITH_MYSTERIES','medium','The lion-headed time-god is part of Mithraic statuary, though its precise role is debated. Clauss ch.13.'),
 ('ENT_MITH_PETRA_GENETRIX','member_of','ENT_MITH_MYSTERIES','high','The birth-giving rock is a core element of Mithraic cosmogonic imagery. Clauss ch.6.'),
 ('ENT_MITH_TAUROCTONY','member_of','ENT_MITH_MYSTERIES','high','The tauroctony is the central cult-scene of the Mithraic mysteries. Beck; Clauss ch.7.'),
 ('ENT_MITH_CAUTES','sibling_of','ENT_MITH_CAUTOPATES','high','Cautes and Cautopates are the paired dadophoroi (twin torchbearers) of Mithras, regularly flanking the tauroctony as a complementary pair. Clauss ch.9.'),
 ('ENT_MITH_CAUTES','associated_with','ENT_SYN_MITHRAS','high','Cautes is an attendant torchbearer of Mithras within the cult scene. Clauss ch.9.'),
 ('ENT_MITH_CAUTOPATES','associated_with','ENT_SYN_MITHRAS','high','Cautopates is an attendant torchbearer of Mithras within the cult scene. Clauss ch.9.'),
 ('ENT_MITH_PETRA_GENETRIX','associated_with','ENT_SYN_MITHRAS','high','Mithras is the petrogenes, born from the petra genetrix; the rock is the source of his cosmogonic birth. Clauss ch.6.'),
 ('ENT_MITH_TAUROCTONY','associated_with','ENT_SYN_MITHRAS','high','The tauroctony depicts Mithras himself slaying the bull; the scene is inseparable from the god. Beck.'),
 ('ENT_MITH_LEONTOCEPHALINE','equated_with','ENT_SYN_AION','medium','The lion-headed Mithraic time-god is widely identified with Aion (and Zurvan), a god of eternity/unbounded time. Interpretatio is scholarly-attested but debated. Clauss ch.13.'),
 ('ENT_MITH_HELIODROMUS','associated_with','ENT_ROM_SOL_INVICTUS','medium','The sixth grade, the Sun-Runner, is placed under Sol and embodies the cult''s solar courier symbolism, linking the grade system to Sol Invictus. Clauss ch.10, ch.12.');
